# OOXML
def bidi(p): p.alignment=WD_ALIGN_PARAGRAPH.RIGHT; p._p.get_or_add_pPr().append(OxmlElement('w:bidi'))
def run(p,text,size=10.5,bold=False,color=INK):
    r=p.add_run(str(text));r.font.name=AR_FONT;r._element.rPr.rFonts.set(qn('w:cs'),AR_FONT);r.font.size=Pt(size);r.font.bold=bold;r.font.color.rgb=RGBColor.from_string(color);return r
def para(d,text,style=None,size=10.5,bold=False,color=INK):
    p=d.add_paragraph(style=style);bidi(p);run(p,text,size,bold,color);return p
def bullets(d,items):
    for x in items: para(d,x,'List Bullet')
def shade(cell,color):
    z=cell._tc.get_or_add_tcPr();s=OxmlElement('w:shd');s.set(qn('w:fill'),color);z.append(s)
def table(d,heads,rows,widths=None):
    t=d.add_table(rows=1,cols=len(heads));t.style='Table Grid';t.alignment=WD_TABLE_ALIGNMENT.CENTER
    for j,h in enumerate(heads):
        c=t.rows[0].cells[j];shade(c,NAVY);c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER;p=c.paragraphs[0];bidi(p);run(p,h,8.7,True,WHITE)
    for i,row in enumerate(rows):
        for j,x in enumerate(row):
            c=t.add_row().cells[j] if j==0 else t.rows[-1].cells[j]
            c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.TOP
            if i%2==0:shade(c,'F2F7F8')
            p=c.paragraphs[0];bidi(p);run(p,x,8.3,False,INK)
            if widths:c.width=Inches(widths[j])
    return t
def document(title,sub):
    d=Document();s=d.styles;s['Normal'].font.name=AR_FONT;s['Normal']._element.rPr.rFonts.set(qn('w:cs'),AR_FONT);s['Normal'].font.size=Pt(10.5)
    for st,sz,col in [('Title',25,NAVY),('Heading 1',17,NAVY),('Heading 2',13,TEAL),('Heading 3',11,GOLD)]:s[st].font.name=AR_FONT;s[st]._element.rPr.rFonts.set(qn('w:cs'),AR_FONT);s[st].font.size=Pt(sz);s[st].font.color.rgb=RGBColor.from_string(col)
    sec=d.sections[0];sec.top_margin=Inches(.55);sec.bottom_margin=Inches(.55);sec.left_margin=Inches(.58);sec.right_margin=Inches(.58)
    p=d.add_paragraph();bidi(p);run(p,title,25,True,NAVY);p=d.add_paragraph();bidi(p);run(p,sub,12,False,TEAL)
    hp=sec.header.paragraphs[0];bidi(hp);run(hp,'تأسيس وعي المسلم المعاصر | الوحدة 5 v0.2',8,True,TEAL);fp=sec.footer.paragraphs[0];fp.alignment=WD_ALIGN_PARAGRAPH.CENTER;run(fp,'إصدار إنتاجي v0.2  •  25 أكتوبر 2026',8,False,MUTED)
    return d

