def ppt_text(sh,text,size=18,bold=False,color=INK,align=PP_ALIGN.RIGHT):
    tf=sh.text_frame;tf.clear();tf.word_wrap=True;tf.margin_left=PInches(.12);tf.margin_right=PInches(.12);tf.margin_top=PInches(.06);tf.vertical_anchor=MSO_ANCHOR.MIDDLE;p=tf.paragraphs[0];p.alignment=align;pr=p._p.get_or_add_pPr();b=OxmlElement('a:bidi');b.set('val','1');pr.append(b);r=p.add_run();r.text=str(text);r.font.name=AR_FONT;r.font.size=PPt(size);r.font.bold=bold;r.font.color.rgb=PRGB.from_string(color)
def box(s,x,y,w,h,text,fill=WHITE,line='D5E3E7',size=18,bold=False,color=INK,rounded=True):
    sh=s.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE if rounded else MSO_SHAPE.RECTANGLE,PInches(x),PInches(y),PInches(w),PInches(h));sh.fill.solid();sh.fill.fore_color.rgb=PRGB.from_string(fill);sh.line.color.rgb=PRGB.from_string(line);ppt_text(sh,text,size,bold,color);return sh
